const teams={VGK:{name:'Vegas Golden Knights',city:'Las Vegas',arena:'T-Mobile Arena',lat:36.1,lon:-115.18},NJD:{name:'New Jersey Devils',city:'Newark',arena:'Prudential Center',lat:40.73,lon:-74.17},FLA:{name:'Florida Panthers',city:'Sunrise',arena:'Amerant Bank Arena',lat:26.16,lon:-80.33},WPG:{name:'Winnipeg Jets',city:'Winnipeg',arena:'Canada Life Centre',lat:49.89,lon:-97.14},CGY:{name:'Calgary Flames',city:'Calgary',arena:'Scotiabank Saddledome',lat:51.04,lon:-114.05},SEA:{name:'Seattle Kraken',city:'Seattle',arena:'Climate Pledge Arena',lat:47.62,lon:-122.35}};
const qs=new URLSearchParams(location.search),a=qs.get('a')||'VGK',b=qs.get('b')||'NJD',root=document.querySelector('#nhl-content'),api='https://api-web.nhle.com/v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const point=t=>({x:85+(t.lon+130)*6.4,y:65+(60-t.lat)*7.6});
async function load(){try{const [standings,s1,s2]=await Promise.all([fetch(`${api}/standings/now`).then(r=>r.json()),fetch(`${api}/club-schedule-season/${a}/20262027`).then(r=>r.json()),fetch(`${api}/club-schedule-season/${a}/20252026`).then(r=>r.json())]);const rows=standings.standings||[],standing=x=>rows.find(r=>r.teamAbbrev?.default===x);const games=[...(s1.games||[]),...(s2.games||[])].filter(g=>(g.awayTeam?.abbrev===b||g.homeTeam?.abbrev===b)&&['OFF','FINAL'].includes(g.gameState)).sort((x,y)=>y.gameDate.localeCompare(x.gameDate)).slice(0,5);render(standing(a),standing(b),games)}catch(e){root.innerHTML='<div class="nhl-error"><h1>Kunde inte hämta NHL-data</h1><p>Försök igen om en liten stund.</p><a href="index.html">Tillbaka till sportguiden</a></div>'}}
function render(sa,sb,games){const ta=teams[a],tb=teams[b],pa=point(ta),pb=point(tb);root.innerHTML=`<section class="match-hero"><p class="eyebrow">NHL · MATCHFAKTA</p><div class="matchup"><div class="club"><img src="https://assets.nhle.com/logos/nhl/svg/${a}_light.svg" alt=""><h1>${esc(ta.name)}</h1><p>${esc(ta.city)}</p></div><div class="versus"><span>MOT</span><i></i></div><div class="club"><img src="https://assets.nhle.com/logos/nhl/svg/${b}_light.svg" alt=""><h1>${esc(tb.name)}</h1><p>${esc(tb.city)}</p></div></div><p class="data-note"><span class="pulse"></span> Uppdaterat från NHL:s officiella data</p></section><section class="nhl-grid"><article class="nhl-card"><p class="eyebrow dark">TABELLEN JUST NU</p><h2>Ligaplacering</h2>${standRow(a,ta,sa)}${standRow(b,tb,sb)}<a href="https://www.nhl.com/standings/" target="_blank">Se hela NHL-tabellen ↗</a></article><article class="nhl-card"><p class="eyebrow dark">SENASTE MÖTENA</p><h2>Inbördes matcher</h2>${games.length?games.map(gameRow).join(''):'<p>Inga avslutade möten hittades.</p>'}<small>Nyaste matchen först.</small></article></section><section class="map-section"><div><p class="eyebrow">VAR LAGEN FINNS</p><h2>Två lag.<br>En kontinent.</h2><div class="map-legend"><p><b>${esc(ta.city)}</b><span>${esc(ta.arena)}</span></p><p><b>${esc(tb.city)}</b><span>${esc(tb.arena)}</span></p></div></div><svg class="na-map" viewBox="0 0 700 470" role="img" aria-label="Karta över Nordamerika"><path d="M88 75L160 35 250 58 310 38 370 78 442 70 525 115 585 178 550 230 510 240 485 300 430 330 397 390 350 423 300 386 280 330 225 288 180 240 125 205 72 145Z"/><path class="route" d="M${pa.x} ${pa.y} Q350 100 ${pb.x} ${pb.y}"/><g class="pin" transform="translate(${pa.x} ${pa.y})"><circle r="13"/><circle r="5"/><text y="-22">${a}</text></g><g class="pin two" transform="translate(${pb.x} ${pb.y})"><circle r="13"/><circle r="5"/><text y="-22">${b}</text></g></svg></section>`}
function standRow(code,t,s){return `<div class="stand-row"><img src="https://assets.nhle.com/logos/nhl/svg/${code}_light.svg" alt=""><div><b>${esc(t.name)}</b><span>${s?`${s.wins}–${s.losses}–${s.otLosses} · ${s.points} poäng`:'Uppgift saknas'}</span></div><strong>${s?`#${s.leagueSequence}`:'–'}</strong></div>`}function gameRow(g){const x=g.awayTeam,y=g.homeTeam;return `<div class="meeting-row"><time>${new Date(g.gameDate+'T12:00:00').toLocaleDateString('sv-SE',{day:'numeric',month:'short',year:'numeric'})}</time><div><span>${esc(x.placeName?.default||x.abbrev)}</span><b>${x.score} – ${y.score}</b><span>${esc(y.placeName?.default||y.abbrev)}</span></div><small>${esc(g.venue?.default||'')}</small></div>`}load();
